from lib import *
chapter(6,'maths','symmetry','Symmetry',
 ('The butterfly','Fold a paper butterfly down its middle and the two wings match exactly. That perfect match is symmetry. Nature, art and buildings are full of it.'),
 [('Line of symmetry',['A shape has a line of symmetry if folding along that line makes the two halves match exactly.','The fold line is called the line of symmetry or axis of symmetry.','A rectangle has 2 lines of symmetry, a square has 4 and an equilateral triangle has 3.','The letter A has one vertical line of symmetry, and H has two.','Some shapes have no line of symmetry, such as a scalene triangle.']),
  ('Reflection',['A mirror placed on the line of symmetry shows the other half. The mirror image is reversed left to right.','To complete a symmetrical figure, reflect each point the same distance on the other side of the line.']),
  ('Rotational symmetry',['A shape has rotational symmetry if it looks the same after turning less than a full turn about a fixed point called the centre.','The number of times it matches in one full turn is its order of rotational symmetry.','A square matches 4 times in one turn, so its order is 4. An equilateral triangle matches 3 times.','A shape can have rotational symmetry without a line of symmetry.'])],
 [('How many lines of symmetry does a regular hexagon have?',[('A regular shape with n sides has n lines of symmetry.','Rule for regular polygons.'),('A hexagon has 6 sides, so 6 lines.','Three through opposite corners and three through opposite sides.')]),
  ('What is the order of rotational symmetry of a plus sign?',[('Turn it by a quarter turn.','It looks the same.'),('It matches 4 times in a full turn, so the order is 4.','Count matches.')])],
 ('How can you check whether a shape has a line of symmetry using paper?',['Cut out the shape and fold it.','If both halves cover each other exactly, the fold is a line of symmetry.'],['Thinking any fold is a line of symmetry.','Forgetting diagonals of a square.']),
 ['A line of symmetry makes two matching halves.','Squares have 4 lines, rectangles 2, equilateral triangles 3.','Rotational symmetry means matching in a turn.','Order is the number of matches in a full turn.'],
 [num('s9-1',1,'How many lines of symmetry does a square have?',4,'Two through the middles of opposite sides and two diagonals.',[(2,'You missed the diagonals.')]),
  mcq('s9-2',1,'Which letter has a vertical line of symmetry?','A',[('F','F has no line of symmetry.'),('R','R is not symmetric.')],'Fold A down the middle and both halves match.'),
  tf('s9-3',1,'A rectangle has 2 lines of symmetry.',True,'The two lines through midpoints of opposite sides.'),
  num('s9-4',1,'How many lines of symmetry does an equilateral triangle have?',3,'One from each corner to the opposite side.',[(1,'All three corners work.')]),
  mcq('s9-5',2,'A circle has','infinitely many lines of symmetry',[('4 lines','Every diameter is a line of symmetry.'),('none','A circle is perfectly symmetrical.')],'Every line through the centre.'),
  num('s9-6',2,'Order of rotational symmetry of a square',4,'It looks the same after every quarter turn.',[(2,'Four quarter turns, not two.')]),
  mcq('s9-7',2,'A shape that turns to match itself in a full turn has','rotational symmetry',[('reflection only','Reflection needs a mirror line.'),('no symmetry','It is symmetrical by rotation.')],'Rotation about a centre.'),
  tf('s9-8',2,'A parallelogram has rotational symmetry of order 2.',True,'It matches after a half turn.'),
  num('s9-9',3,'A regular pentagon has how many lines of symmetry?',5,'One for each corner.',[(10,'Each line passes a corner and a side.')]),
  mcq('s9-10',3,'The letter N has','rotational symmetry but no line of symmetry',[('a line but no rotational symmetry','N does not fold to match.'),('both','N has no fold line.')],'Turn N a half turn and it matches.')],
 keep=['symmetry','reflection','rotation'])
